export const openCashDrawer = async (data: CashDrawerInput, options?: RequestInit): Promise<CashDrawerSession> =>
  customFetch<CashDrawerSession>(`/api/accounting/cash-drawer`, { ...options, method: 'POST', body: JSON.stringify(data) });

export function useOpenCashDrawer(options?: { mutation?: UseMutationOptions<CashDrawerSession, ErrorType<unknown>, CashDrawerInput> }) {
  return useMutation({ mutationFn: (data: CashDrawerInput) => openCashDrawer(data), ...options?.mutation });
}

export const closeCashDrawer = async (id: number, data: CashDrawerCloseInput, options?: RequestInit): Promise<CashDrawerSession> =>
  customFetch<CashDrawerSession>(`/api/accounting/cash-drawer/${id}/close`, { ...options, method: 'PATCH', body: JSON.stringify(data) });

export function useCloseCashDrawer(options?: { mutation?: UseMutationOptions<CashDrawerSession, ErrorType<unknown>, { id: number; data: CashDrawerCloseInput }> }) {
  return useMutation({ mutationFn: ({ id, data }: { id: number; data: CashDrawerCloseInput }) => closeCashDrawer(id, data), ...options?.mutation });
}

// Customer payment
export const recordCustomerPayment = async (
  id: number, data: { amount: number; method?: string; notes?: string }, options?: RequestInit
): Promise<{ customerId: number; amount: number; method: string; newBalance: number; createdAt: string }> =>
  customFetch(`/api/customers/${id}/payments`, { ...options, method: 'POST', body: JSON.stringify(data) });

export function useRecordCustomerPayment(options?: { mutation?: UseMutationOptions<any, ErrorType<unknown>, { id: number; data: { amount: number; method?: string; notes?: string } }> }) {
  return useMutation({ mutationFn: ({ id, data }: { id: number; data: any }) => recordCustomerPayment(id, data), ...options?.mutation });
}

